import{_ as a,o,c as t,ae as i}from"./chunks/framework.DCJ5T8RY.js";const m=JSON.parse('{"title":"多语言的判断优先级","description":"","frontmatter":{"title":"多语言的判断优先级","date":"2020-03-05"},"headers":[],"relativePath":"2020/language-detection-priority.md","filePath":"2020/language-detection-priority.md","lastUpdated":1786185344000}'),l={name:"2020/language-detection-priority.md"};function r(n,e,c,d,p,s){return o(),t("div",null,[...e[0]||(e[0]=[i('<h3 id="写在前面" tabindex="-1">写在前面 <a class="header-anchor" href="#写在前面" aria-label="Permalink to &quot;写在前面&quot;">​</a></h3><p>最近增加Node多语言的支持，后端获取语言参数的优先级有点不清楚<br> 特意查了些文档，在这里记录一下</p><h3 id="优先级" tabindex="-1">优先级 <a class="header-anchor" href="#优先级" aria-label="Permalink to &quot;优先级&quot;">​</a></h3><ol><li>Domain: 顶级域名（TLD, Top Level Domain），如.cn, .de等</li><li>Subdomain: 子域名，如<code>cn.amazon.com</code></li><li>Subdirectory: URL里增加path，如<code>www.mozilla.org/en-US/</code></li><li>其他: 以下不分先后，可自定义优先级 <ul><li>URL parameter: 如<code>www.example.com?lang=en-US</code></li><li>HTTP header: <code>Accept-Language</code>: 可在浏览器语言偏好里设置，请求时会将此信息带上<code>&#39;Accept-Language: en;q=0.8,es;q=0.6,fr;q=0.4&#39;</code></li><li>User Agent: 一般用在App内，语言参数名称可能不标准，而且变更可能比较频繁，比如Facebook的UA里表示语言的属性是user-lang</li><li>Cookie: 语言参数名也可能不标准，变更也可能比较频繁，现在好像用的越来越少了</li></ul></li><li>IP查找: 以上都失效的时候，后端还可以考虑使用IP查找检测对应语言，准确率较低</li><li>自定义标准: 还可以自定义规则覆盖以上的设置</li></ol><p>暂时这么多，以上</p>',5)])])}const u=a(l,[["render",r]]);export{m as __pageData,u as default};
